head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > P > displayFormat]<br/>Calendar 컴포넌트 하단에 표시되는 선택일의 포맷을 마스크 문자로 설정합니다.",
    "validation" : [
        "선택일이 표시되는 포맷을 'y', 'M', 'd', 'E', 'H', 'm', 'S' 마스크 문자로 설정합니다.",
        "'yyyy' 마스크는 년도와 매칭되며 네자리로 설정합니다.",
        "'MM' 마스크는 월과 매칭되며 두자리로 설정합니다.",
        "'dd' 마스크는 일과 매칭되며 두자리로 설정합니다.",
        "'EEE' 마스크는 요일과 매칭되며 세자리로 설정합니다.",
        "'HH' 마스크는 시와 매칭되며 두자리로 설정합니다.",
        "'mm' 마스크는 분과 매칭되며 두자리로 설정합니다.",
        "'SS' 마스크는 초와 매칭되며 두자리로 설정합니다.",
        "마스크 문자가 아닌 일반문자는 그대로 표시됩니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        displayFormat : con_displayFormat.getText(),
        // 하단 currentDate 영역이 표시되는 모드 (yearMonthDate, yearMonthDateHour 만 하단 표시됨)
        calendarValueType : "yearMonthDateHour"
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick"]);

    await $c.gcm.createBasicCalendar(cList, eList);

    // 초기 선택일 설정 (calendarValueType=yearMonthDateHour → 10자리 yyyyMMddHH)
    target1.gotoCalendar("2025051812");
}



scwin.btn_getDisplayedText_onclick = function (e) {
    // calendar 내부 currentDate 영역
    const element = target1.render.querySelector('[id$="_currentDate"]')
                 || target1.render.querySelector('[class*="currentDate"]');

    if (element) {
        // validation: 마스크 문자(yyyy/MM/dd/EEE/HH/mm/SS) 자릿수 매칭 + 마스크 외 일반문자 그대로 표시
        wf_body_bottom.getObj("scwin").setReturnValue("[하단 선택일 표시] '" + element.textContent + "' (displayFormat='" + target1.options.displayFormat + "')");
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue('currentDate 영역을 찾을 수 없음');
    }
};
